import { useQuery, useQueryClient } from "@tanstack/react-query"
import { Check, ImageIcon } from "lucide-react"
import { toast } from "sonner"
import { Badge } from "@/components/ui/badge"
import { api, put, type ImageGenerator } from "@/lib/api"

/** Pictures the pack does not have, generated by the author's own Codex CLI. */
export function ImageSettings() {
  const queryClient = useQueryClient()
  const images = useQuery({ queryKey: ["images"], queryFn: () => api<ImageGenerator>("/api/images") })
  const save = async (patch: { enabled?: boolean; limit?: number }) => {
    try {
      queryClient.setQueryData(["images"], await put<ImageGenerator>("/api/images", patch))
    } catch (error) {
      toast.error((error as Error).message)
    }
  }
  const data = images.data
  if (!data) return null
  const limits = Array.from({ length: data.limits.max - data.limits.min + 1 }, (_, i) => data.limits.min + i)

  return (
    <div className="grid gap-3 rounded-lg border p-4">
      <div className="flex flex-wrap items-center gap-2">
        <ImageIcon className="size-4" />
        <span className="font-medium">Генерация картинок</span>
        <Badge variant="secondary">через Codex CLI</Badge>
        {data.codexSignedIn
          ? <span className="inline-flex items-center gap-1 text-xs text-muted-foreground"><Check className="size-3" />Codex подключён</span>
          : <span className="text-xs text-destructive">Codex не подключён</span>}
      </div>
      <p className="text-sm text-muted-foreground">
        Когда в пакете нет картинки нужного предмета или сцены, агент генерирует её в стиле пакета: прозрачной наклейкой или сценой на весь кадр. Генерирует ваш Codex по подписке ChatGPT, лимиты подписки расходуются, одна картинка — около минуты. Себя, реальных людей, логотипы и текст агент не генерирует.
      </p>
      {!data.codexSignedIn && (
        <p className="text-sm text-muted-foreground">Войдите в Codex в разделе «Агент»: <code className="rounded bg-muted px-1">codex login --device-auth</code>. Монтировать при этом может и Claude Code.</p>
      )}
      <label className="flex items-center gap-2 text-sm">
        <input type="checkbox" className="size-4 accent-primary" checked={data.enabled} onChange={(e) => save({ enabled: e.target.checked })} />
        Агент может генерировать картинки
      </label>
      <label className="flex flex-wrap items-center gap-2 text-sm">
        Не больше
        <select className="rounded-md border bg-background px-2 py-1" value={data.limit} disabled={!data.enabled} onChange={(e) => save({ limit: Number(e.target.value) })}>
          {limits.map((n) => <option key={n} value={n}>{n}</option>)}
        </select>
        картинок на ролик; каждую можно переделать дважды.
      </label>
    </div>
  )
}
